&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(29, 28, 29); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Experienced working in a cloud environment utilizing AWS, GCP, Kubernetes, or Docker&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;&lt;span style=&quot;color: rgb(29, 28, 29); font-family: helvetica, arial, sans-serif; font-size: 10pt;&quot;&gt;Contributions to open source AI or data projects&lt;/span&gt;&lt;/li&gt;
